package vault                    // the only package that may name the store

type Vault struct {
	store  *store.Type        // unexported: not nameable outside package vault
	policy Policy
}

func (v *Vault) Read(who Subject, id string) (Record, error) {
	if !v.policy.Allows(who, id) {
		return Record{}, ErrDenied        // decided before the store is touched
	}
	return v.store.Load(id)
}
